insert into public.question_bank (subject_code, grade, topic_id, topic_name, form, qtype, difficulty, difficulty_source, question, content_hash, archived, note)
select 'vat-ly', '12', v.tid, v.tname, 'bai_tap', v.q->>'type', v.q->>'difficulty', 'ai', v.q, public.question_content_hash(v.q), true, 'nap-vl12-c4-20261024'
from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Năm 1897 Tôm-xơn khi nghiên cứu hiện tượng phóng điện trong chân không đã phát hiện ra tia âm cực, mà bản chất là chùm các hạt nhỏ bé mang điện tích âm, gọi là các electron. Kí hiệu của hạt electron là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Electron là hạt mang điện tích âm, kí hiệu là $e$ (hay $e^-$).</p><p class=\"text-base leading-relaxed my-2\">Các kí hiệu còn lại: $p$ là proton, $n$ là nơtron, $m$ thường chỉ khối lượng, không phải kí hiệu electron.</p>","options":["p.","e.","n.","m."],"answer":1}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong nguyên tử, lớp vỏ mang điện tích âm là do:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lớp vỏ nguyên tử gồm các electron, mỗi electron mang điện tích âm.</p><p class=\"text-base leading-relaxed my-2\">Proton mang điện dương và nằm trong hạt nhân, nơtron không mang điện; nguyên tử trung hòa chỉ là hệ quả của việc điện tích âm và dương cân bằng, không phải nguyên nhân vỏ mang điện âm.</p>","options":["Chứa hạt electron mang điện âm","Chứa hạt proton và notron đều mang điện tích dương","Chứa hạt proton mang điện tích âm","Do nguyên tử trung hòa về điện."],"answer":0}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Thí nghiệm nào đã khám phá ra hạt nhân nguyên tử của Rutherford</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Rutherford bắn chùm hạt $\\alpha$ vào lá vàng rất mỏng, quan sát thấy một số ít hạt bị lệch hướng mạnh, từ đó phát hiện hạt nhân nguyên tử.</p><p class=\"text-base leading-relaxed my-2\">Bắn $\\alpha$ vào nitơ là thí nghiệm phát hiện proton; bắn $\\alpha$ vào beryli là thí nghiệm của Chadwick phát hiện nơtron; phóng điện trong ống chân không là thí nghiệm phát hiện electron.</p>","options":["Bắn phá 1 chùm hạt alpha lên 1 lá vàng siêu mỏng.","Phóng điện trong một ống thủy tinh gần như chân không.","Bắn phá hạt nhân nguyên tử Nitrogen bằng các hạt α.","Dùng hạt α để bắn phá hạt nhân nguyên tử Beryllium"],"answer":0}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Kết quả nào trong thí nghiệm bắn phá lá vàng của Rutherford chỉ ra sự tồn tại của hạt nhân nguyên tử?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong thí nghiệm lá vàng, phần lớn hạt $\\alpha$ đi thẳng, chỉ một số ít bị lệch hướng (có hạt bật ngược lại).</p><p class=\"text-base leading-relaxed my-2\">Hạt $\\alpha$ mang điện dương bị lệch do đẩy bởi một vùng nhỏ mang điện dương, khối lượng lớn: đó là hạt nhân. Vậy kết quả chỉ ra hạt nhân là: một số hạt bị lệch hướng.</p>","options":["Đa số hạt bay xuyên qua lá vàng với hướng di chuyển không đổi.","Một số hạt bị lệch hướng di chuyển so với hướng di chuyển ban đầu.","Đa số hạt bị lệch hướng di chuyển so với hướng di chuyển ban đầu.","Một số hạt bay xuyên qua lá vàng với hướng di chuyển không đổi."],"answer":1}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong thí nghiệm bắn lá vàng của Rutherford, hiện tượng hầu hết tia α đều xuyên qua lá vàng, hiện tượng này chứng minh</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hầu hết hạt $\\alpha$ xuyên qua lá vàng không đổi hướng nghĩa là trên đường đi chúng hầu như không gặp vật cản.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ nguyên tử có cấu trúc phần lớn là rỗng.</p><p class=\"text-base leading-relaxed my-2\">Hạt nhân nhỏ, đặc khít được suy ra từ hiện tượng một số ít hạt bị lệch mạnh, không phải từ hiện tượng này.</p>","options":["nguyên tử có cấu trúc phần lớn là rỗng.","nguyên tử có cấu trúc đặc khít.","nguyên tử có hạt nhân đặc khít nhưng chiếm một thể tích rất nhỏ.","nguyên tử trung hòa về điện."],"answer":0}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Thí nghiệm tìm ra hạt nhân nguyên tử của Rutherford đã chứng minh dự đoán nào sau đây về nguyên tử là sai?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Mô hình Thomson cho rằng điện tích dương phân bố đều trong toàn nguyên tử. Thí nghiệm Rutherford cho thấy điện tích dương tập trung ở hạt nhân rất nhỏ ở tâm.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ dự đoán điện tích dương phân bố đều là sai.</p><p class=\"text-base leading-relaxed my-2\">Các phương án B, C, D phù hợp với kết quả thí nghiệm.</p>","options":["Trong nguyên tử các điện tích dương được phân bố đều trong toàn bộ nguyên tử.","Trong nguyên tử ngoài các hạt electron mang điện âm còn có các hạt mang điện tích dương.","Hạt nhân mang điện tích dương có kích thước rất nhỏ so với nguyên tử.","Hạt nhân mang điện tích dương trung hòa các điện tích âm của các hạt electron."],"answer":0}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khẳng định nào sau đây là đúng khi so sánh kích thước của hạt nhân so với kích thước của nguyên tử?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường kính hạt nhân cỡ $10^{-15}$ m, đường kính nguyên tử cỡ $10^{-10}$ m.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ hạt nhân có kích thước rất nhỏ so với nguyên tử.</p>","options":["Kích thước hạt nhân rất nhỏ so với nguyên tử.","Hạt nhân có kích thước bằng một nửa nguyên tử.","Hạt nhân chiếm gần như toàn bộ kích thước nguyên tử.","Hạt nhân có kích thước bằng 2/3 kích thước nguyên tử."],"answer":0}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nếu xem nguyên tử như một quả cầu thì khẳng định nào dưới đây là đúng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường kính nguyên tử cỡ $10^{-10}$ m, đường kính hạt nhân cỡ $10^{-14}$ đến $10^{-15}$ m.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ đường kính nguyên tử lớn hơn đường kính hạt nhân cỡ vài chục nghìn lần; trong các phương án chỉ có 10000 lần là phù hợp.</p><p class=\"text-base leading-relaxed my-2\">Phần chữ in đậm ở cuối phương án D là tiêu đề mục bị lẫn từ file Word, không thuộc đề.</p>","options":["Đường kính nguyên tử gần bằng đường kính của hạt nhân","Đường kính của nguyên tử gấp 10 lần đường kính của hạt nhân","Đường kính của nguyên tử gấp 4 lần đường kính của hạt nhân","Đường kính của nguyên tử gấp 10000 lần đường kính của hạt nhân"],"answer":3}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nguyên tử là hạt vô cùng nhỏ, trung hòa về điện, nên:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Nguyên tử trung hòa về điện nên tổng điện tích dương của proton bằng tổng điện tích âm của electron.</p><p class=\"text-base leading-relaxed my-2\">Vì proton và electron có điện tích cùng độ lớn nên số proton bằng số electron.</p><p class=\"text-base leading-relaxed my-2\">Số proton không nhất thiết bằng số nơtron, và khối lượng electron nhỏ hơn rất nhiều so với proton hay nơtron.</p>","options":["số proton bằng số electron.","số proton bằng số nơtron.","khối lượng electron bằng khối lượng proton.","khối lượng nơtrơn bằng khối lượng electron."],"answer":0}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Điện tích của electron</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện tích của electron là $-e$, điện tích của proton là $+e$ với $e = 1,6.10^{-19}$ C.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ cùng độ lớn, trái dấu.</p>","options":["cùng độ lớn, trái dấu với điện tích của proton.","cùng độ lớn, cùng dấu với điện tích của proton.","có độ lớn lớn hơn, trái dấu với điện tích của proton.","có độ lớn nhỏ hơn, trái dấu với điện tích của proton."],"answer":0}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Vào năm 1932, khi dùng các hạt 𝛼 để bắn phá hạt nhân nguyên tử beryllium, Chadwick nhận thấy sự xuất hiện của một loại hạt có khối lượng xấp xỉ hạt proton nhưng không mang điện. Ông gọi chúng là hạt:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Năm 1932 Chadwick bắn hạt $\\alpha$ vào beryli và phát hiện hạt không mang điện, khối lượng xấp xỉ proton, gọi là nơtron (neutron).</p>","options":["electron.","proton.","neutron.","phage."],"answer":2}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu trả lời sai. Nguyên tử có cấu tạo như thế nào?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Mỗi nguyên tử chỉ có một hạt nhân ở tâm và các electron quay xung quanh. Các phương án A, B, C đều đúng.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ phương án D (nguyên tử có thể có nhiều hạt nhân) là sai.</p>","options":["Nguyên tử có một hạt nhân và các hạt electron.","Hạt nhân mang điện tích dương, nằm ở tâm nguyên tử; các electron mang điện tích âm quay xung quanh hạt nhân.","Tổng các điện tích âm của các electron có trị số tuyệt đối bằng điện tích dương của hạt nhân, bình thường nguyên tử trung hòa về điện.","Nguyên tử có thể có nhiều hạt nhân và nhiều hạt electron."],"answer":3}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khối lượng của nguyên tử tập trung chủ yếu ở hạt nhân vì</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng electron nhỏ hơn rất nhiều (cỡ $\\frac{1}{1836}$) so với proton và nơtron, nên khối lượng nguyên tử gần như bằng khối lượng hạt nhân.</p><p class=\"text-base leading-relaxed my-2\">Kích thước nhỏ hay trung hòa điện không giải thích được khối lượng tập trung ở hạt nhân.</p>","options":["nguyên tử trung hòa về điện","kích thước của hạt nhân nhỏ hơn rất nhiều lần so với kích thước nguyên tử.","vỏ nguyên tử có kích thước không đáng kể so với nguyên tử.","khối lượng hạt electron nhỏ hơn rất nhiều so với khối lượng của hạt proton và neutron."],"answer":3}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Điều nhận định nào sau đây là không đúng:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng nguyên tử gồm khối lượng hạt nhân (proton, nơtron) cộng khối lượng các electron (rất nhỏ nhưng không bằng 0).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ nói khối lượng nguyên tử bằng tổng khối lượng proton và nơtron là không chính xác; các phương án A, B, C đúng.</p>","options":["Nguyên tử có cấu tạo rỗng, hạt nhân mang điện tích dương có kích thước rất nhỏ so với kích thước của nguyên tử và nằm ở tâm của nguyên tử","Khối lượng của nguyên tử tập trung hầu hết ở hạt nhân, khối lượng của electron không đáng kể so với khối lượng của nguyên tử","Tổng trị số điện tích âm của electron trong lớp vỏ nguyên tử bằng tổng trị số điện tích dương của proton nằm trong hạt nhân nguyên tử","Khối lượng tuyệt đối của nguyên tử bằng tổng số khối lượng của proton và nơtron trong hạt nhân"],"answer":3}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong thành phần cấu tạo của các nguyên tử, không có hạt nào dưới đây?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Nguyên tử gồm proton, nơtron (trong hạt nhân) và electron (ở vỏ).</p><p class=\"text-base leading-relaxed my-2\">Phôtôn là hạt ánh sáng, không phải thành phần của nguyên tử.</p>","options":["Prôtôn.","Nơtron.","Phôtôn.","Êlectron."],"answer":2}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân được cấu tạo từ</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân được cấu tạo từ các proton và các nơtron (gọi chung là nuclôn); electron nằm ở vỏ nguyên tử.</p>","options":["các prôtôn.","các prôtôn và các nơtron.","các nơtron.","các prôtôn, nơtron và êlectron."],"answer":1}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hệ Mặt Trời gồm Mặt Trời ở trung tâm và các thiên thể quay quanh theo những quỹ đạo xác định. Hãy cho biết mô hình nguyên tử của nhà khoa học nào được gọi là mô hình hành tinh nguyên tử, tương tự như hệ Mặt Trời?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Mô hình hành tinh nguyên tử: electron chuyển động quanh hạt nhân như các hành tinh quanh Mặt Trời, là mô hình Rutherford - Bohr.</p><p class=\"text-base leading-relaxed my-2\">Thomson đề xuất mô hình bánh mì nho khô, Chadwick phát hiện nơtron.</p>","options":["Mô hình nguyên tử Thomson.","Mô hình nguyên tử Chadwick.","Mô hình nguyên tử Rutherford - Bohr.","Mô hình nguyên tử Newton."],"answer":2}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Theo mô hình Rutherford-Bohr, các electron trong nguyên tử chuyển động trong khu vực không gian xung quanh hạt nhân</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong mô hình Rutherford - Bohr, electron chuyển động quanh hạt nhân theo các quỹ đạo xác định, giống các hành tinh quanh Mặt Trời.</p><p class=\"text-base leading-relaxed my-2\">Phương án A (không theo quỹ đạo xác định) thuộc mô hình đám mây electron của cơ học lượng tử.</p>","options":["không theo quỹ đạo xác định.","theo quỹ đạo giống như các hành tinh xung quanh mặt trời.","không chuyển động.","theo quỹ đạo hình số tám."],"answer":1}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Năm 1913, Bo đã vận dụng thuyết lượng tử ánh sáng vào hệ thống nguyên tử và đề ra một mẫu nguyên tử mới mang tên mình. Mẫu này về cơ bản vẫn giữ mô hình hành tinh nguyên tử của Rutherford nhưng bổ sung thêm 2 tiên đề có tên gọi là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Bohr bổ sung hai tiên đề: tiên đề về các trạng thái dừng và tiên đề về sự hấp thụ - bức xạ năng lượng khi nguyên tử chuyển giữa các trạng thái dừng.</p>","options":["tiên đề về độ rộng vùng cấm giữa các nguyên tử để giam hãm chúng.","tiên đề về vùng bẻ gãy mức năng lượng và tăng tốc nhảy vọt của các nguyên tử.","tiên đề về các trạng thái dừng và tiên đề về hấp thụ - bức xạ năng lượng.","tiên đề về mức năng lượng và sự kìm hãm các nguyên tử chuyển động."],"answer":2}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hãy chọn cụm từ thích hợp điền vào chỗ trống sau: Nguyên tử chỉ tồn tại trong những ...(1)..., gọi là các trạng thái dừng. Khi ở trạng thái dừng, nguyên tử ...(2)...</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tiên đề Bohr thứ nhất: nguyên tử chỉ tồn tại trong những trạng thái có năng lượng xác định, gọi là trạng thái dừng; ở trạng thái dừng nguyên tử không bức xạ.</p><p class=\"text-base leading-relaxed my-2\">Trạng thái cơ bản chỉ là một trạng thái dừng có năng lượng thấp nhất, không phải mọi trạng thái dừng.</p>","options":["trạng thái có năng lượng xác định; phát xạ.","trạng thái có năng lượng xác định; không phát xạ.","trạng thái cơ bản; không phát xạ.","trạng thái cơ bản; phát xạ."],"answer":1}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nhà bác học Bohr vận dụng thuyết lượng tử đã giải thích thành công:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Thuyết lượng tử của Bohr giải thích thành công sự tạo thành quang phổ vạch của nguyên tử hiđrô.</p><p class=\"text-base leading-relaxed my-2\">Tán sắc và giao thoa ánh sáng giải thích bằng tính chất sóng, hiện tượng quang điện do Einstein giải thích.</p>","options":["Sự tán sắc ánh sáng.","Hiện tượng quang điện.","Sự giao thoa ánh sáng.","Sự tạo thành quang phổ vạch của nguyên tử Hiđrô."],"answer":3}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Xét các electron chuyển động quanh hạt nhân của một nguyên tử. Thế năng của electron trong điện trường của hạt nhân tại vị trí của các electron nằm cách hạt nhân lần lượt là $r_{0}$, $2r_{0}$ và $3r_{0}$ lần lượt là $W_{1}$, $W_{2}$ và $W_{3}$. Chọn phương án đúng.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Thế năng của electron trong điện trường của hạt nhân (chọn gốc ở vô cực): $W = -\\dfrac{k e^2}{r}$, nhỏ hơn 0 và có giá trị âm càng lớn khi $r$ càng nhỏ.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$W_1 = -\\dfrac{ke^2}{r_0}$, $W_2 = -\\dfrac{ke^2}{2r_0}$, $W_3 = -\\dfrac{ke^2}{3r_0}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$W_1 \\lt W_2 \\lt W_3$.</p><p class=\"text-base leading-relaxed my-2\">Các hệ thức A, B sai vì $W$ không tỉ lệ nghịch như vậy với các hệ số 2, 3 (chúng đều dương/âm không khớp).</p>","options":["$2W_{1}$ = $W_{2}$ = $3W_{3}$.","$3W_{1}$ = $2W_{2}$ = $W_{3}$.","$W_{1}$ $\\lt$ $W_{2}$ $\\lt$ $W_{3}$.","$W_{1}$ $\\gt$ $W_{2}$ $\\gt$ $W_{3}$."],"answer":2}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân nguyên tử được cấu tạo</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân nguyên tử được cấu tạo từ các nuclôn (proton và nơtron); không có electron trong hạt nhân.</p>","options":["từ các nuclôn.","từ các electron.","chỉ từ các hạt nơtron.","chỉ từ các hạt prôton."],"answer":0}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
