($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đồng vị là những nguyên tử mà hạt nhân</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các nguyên tử đồng vị có hạt nhân cùng số $Z$ nhưng khác số khối $A$.</p>","options":["có cùng khối lượng.","cùng số Z, khác số A","cùng số Z, cùng số A","cùng số A"],"answer":1}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tính chất hoá học của một nguyên tử phụ thuộc:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tính chất hoá học do lớp electron quyết định, mà số electron bằng $Z$ (nguyên tử số).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ tính chất hoá học phụ thuộc nguyên tử số.</p>","options":["nguyên tử số.","số khối.","khối lượng nguyên tử.","số các đồng vị."],"answer":0}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hãy chọn phát biểu đúng.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các đồng vị cùng $Z$ nên cùng cấu hình electron, do đó có cùng tính chất hoá học.</p><p class=\"text-base leading-relaxed my-2\">Khối lượng khác nhau nên tính chất vật lí (như khối lượng riêng, nhiệt độ sôi) khác nhau; vậy chỉ B đúng.</p>","options":["Các chất đồng vị có cùng tính chất vật lí.","Các chất đồng vị có cùng tính chất hoá học.","Các chất đồng vị có cùng cả tính chất vật lí lẫn tính chất hoá học.","Các chất đồng vị không có cùng tính chất vật lí và tính chất hoá học."],"answer":1}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đồng vị hiđro nặng $_{1}^{2}H$ còn được gọi là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$_{1}^{2}H$ gọi là đơteri; $_{1}^{3}H$ gọi là triti.</p>","options":["triti.","đơteri.","pôzitron.","nơtrinô."],"answer":1}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Để đo khối lượng nguyên tử, phân tử, thế giới sử dụng đơn vị khối lượng nguyên tử amu (Atomic mass unit) với quy ước 1 đơn vị amu bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đơn vị khối lượng nguyên tử (amu hay u) bằng $\\dfrac{1}{12}$ khối lượng một nguyên tử $_{6}^{12}C$.</p>","options":["khối lượng của 1 proton.","khối lượng của 1 neutron.","khối lượng của 1 nguyên tử $_{6}^{12}C$","1/12 khối lượng của 1 nguyên tử  $_{6}^{12}C$"],"answer":3}$q$::jsonb, 222, $q$Kích thước, khối lượng hạt nhân và đơn vị u$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đơn vị khối lượng nguyên tử, kí hiệu là:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đơn vị khối lượng nguyên tử được kí hiệu là u.</p>","options":["A","u","a","N"],"answer":1}$q$::jsonb, 222, $q$Kích thước, khối lượng hạt nhân và đơn vị u$q$)) as v(q, tid, tname)
