from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây không đúng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Prôtôn và nơtron có khối lượng xấp xỉ 1 u (prôtôn mang điện dương, nơtron không mang điện). Electron mang điện âm và khối lượng rất nhỏ so với 1 u (khoảng $5{,}5\\cdot10^{-4}$ u).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ phát biểu D sai: electron có khối lượng nhỏ hơn 1 u và mang điện âm.</p>","options":["Hạt proton có khối lượng xấp xỉ 1 amu và mang điện tích dương.","Hạt neutron có khối lượng xấp xỉ 1 amu và không mang điện.","Hạt electron có khối lượng bé hơn 1 amu và mang điện tích âm.","Hạt electron có khối lượng lớn hơn 1 amu và không mang điện."],"answer":3}$q$::jsonb, 222, $q$Kích thước, khối lượng hạt nhân và đơn vị u$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hãy chọn phát biểu đúng.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$_{1}^{1}H$ có khối lượng xấp xỉ 1 u; $_{1}^{2}H$ có khối lượng xấp xỉ 2 u.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$_{1}^{2}H$ nặng gần gấp đôi $_{1}^{1}H$ (không chính xác gấp đôi vì khối lượng hạt nhân không đúng bằng tổng khối lượng các nuclôn).</p>","options":["Hạt nhân $_{1}^{1}H$ nặng gấp đôi hạt nhân $_{1}^{2}H$","Hạt nhân $_{1}^{2}H$ nặng gấp đôi hạt nhân $_{1}^{1}H$","Hạt nhân  $_{1}^{2}H$ nặng gần gấp đôi hạt nhân  $_{1}^{1}H$","Hạt nhân $_{1}^{2}H$ nặng bằng hạt nhân $_{1}^{1}H$"],"answer":2}$q$::jsonb, 222, $q$Kích thước, khối lượng hạt nhân và đơn vị u$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu trả lời sai. Đơn vị đo khối lượng trong vật lí hạt nhân:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong vật lí hạt nhân, khối lượng được đo bằng gam (kg), đơn vị khối lượng nguyên tử u, hoặc $\\mathrm{eV}/c^2$, $\\mathrm{MeV}/c^2$.</p><p class=\"text-base leading-relaxed my-2\">MeV là đơn vị của năng lượng, không phải của khối lượng nên phát biểu ở B là sai.</p><p class=\"text-base leading-relaxed my-2\">Vậy chọn B (câu hỏi yêu cầu chọn phát biểu sai).</p>","options":["gam","đơn vị là MeV","đơn vị eV/c$^{2}$ hoặc MeV/c$^{2}$","đơn vị khối lượng nguyên tử (u)"],"answer":1}$q$::jsonb, 222, $q$Kích thước, khối lượng hạt nhân và đơn vị u$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Lực hạt nhân là lực nào sau đây?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực hạt nhân là lực tương tác mạnh giữa các nuclôn, giữ cho các nuclôn liên kết trong hạt nhân.</p><p class=\"text-base leading-relaxed my-2\">Lực điện, lực từ, lực hấp dẫn (giữa các thiên hà) đều không phải lực hạt nhân. Vậy chọn C.</p>","options":["Lực điện.","Lực từ","Lực tương tác giữa các nuclôn.","Lực tương tác giữa các thiên hà."],"answer":2}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tìm phát biểu sai về lực hạt nhân.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực hạt nhân là lực hút rất mạnh giữa các nuclôn, không phụ thuộc điện tích, chỉ tác dụng trong phạm vi cỡ kích thước hạt nhân, có bản chất khác lực tĩnh điện và lực hấp dẫn (các phát biểu A, B, D đúng).</p><p class=\"text-base leading-relaxed my-2\">Lực giữ êlectron quanh hạt nhân là lực tĩnh điện (Culông), không phải lực hạt nhân. Do đó phát biểu C sai.</p>","options":["Là lực chỉ phát huy tác dụng trong phạm vi kích thước hạt nhân.","Là lực tương tác mạnh và không phụ thuộc vào điện tích.","Là lực liên kết giữa hạt nhân và các êlectron quanh hạt nhân giúp nguyên tử bền vững.","Là lực hút rất mạnh giữa các nuclôn, có bản chất khác lực tĩnh điện và lực hấp dẫn."],"answer":2}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn phát biểu sai khi nói về lực hạt nhân</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực hạt nhân không phụ thuộc vào điện tích của nuclôn: lực giữa p-p, p-n, n-n là như nhau.</p><p class=\"text-base leading-relaxed my-2\">Vậy phát biểu B (phụ thuộc điện tích) là sai. Các phát biểu A, C ($\\approx 10^{-15}$ m), D đều đúng.</p>","options":["Lực hạt nhân có tác dụng liên kết các nuclôn với nhau.","Lực hạt nhân phụ thuộc vào điện tích của các nuclôn.","Lực hạt nhân có bán kính tác dụng khoảng 10$^{−15}$ m.","Lực hạt nhân có cường độ rất lớn so với lực điện từ và lực hấp dẫn."],"answer":1}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tìm phát biểu sai về lực hạt nhân: Lực hạt nhân</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo chương trình, lực hạt nhân là lực hút giữa các nuclôn, có trị số lớn hơn lực đẩy Culông giữa các prôtôn và chỉ tác dụng khi khoảng cách giữa các nuclôn cỡ kích thước hạt nhân hoặc nhỏ hơn.</p><p class=\"text-base leading-relaxed my-2\">Phát biểu B sai vì lực hạt nhân không trở thành lực đẩy khi khoảng cách lớn: khi nuclôn cách xa hơn kích thước hạt nhân thì lực này coi như bằng 0 (đúng như D).</p>","options":["có trị số lớn hơn cả lực đẩy culông giữa các prôtôn.","là lực hút khi khoảng cách giữa hai nuclôn nhỏ hơn kích thước hạt nhân và là lực đẩy khi khoảng cách giữa chúng lớn.","chỉ là lực hút.","không có tác dụng khi các nuclôn cách xa nhau hơn kích thước hạt nhân."],"answer":1}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính độ hụt khối và năng lượng liên kết","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Độ hụt khối của một hạt nhân bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Độ hụt khối là hiệu giữa tổng khối lượng các nuclôn riêng rẽ và khối lượng hạt nhân: $\\Delta m = Zm_p + (A-Z)m_n - m_X$.</p><p class=\"text-base leading-relaxed my-2\">Vậy chọn C. Phương án B có dấu ngược; D dùng khối lượng nguyên tử nên sai.</p>","options":["tổng khối lượng các nuclôn có trong hạt nhân và khối lượng hạt nhân.","khối lượng hạt nhân trừ tổng khối lượng các nuclôn cấu tạo nên hạt nhân đó.","tổng khối lượng các nuclôn có trong hạt nhân trừ khối lượng hạt nhân.","tổng khối lượng các nuclôn có trong hạt nhân trừ khối lượng nguyên tử."],"answer":2}$q$::jsonb, 223, $q$Tính độ hụt khối và năng lượng liên kết$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính độ hụt khối và năng lượng liên kết","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là đúng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết của hạt nhân là năng lượng tối thiểu cần cung cấp để tách hạt nhân thành các nuclôn riêng rẽ (bằng năng lượng toả ra khi các nuclôn liên kết thành hạt nhân).</p><p class=\"text-base leading-relaxed my-2\">Phương án A, C, D nói đến năng lượng toàn phần của nguyên tử hoặc liên kết với êlectron nên sai. Chọn B.</p>","options":["Năng lượng liên kết là toàn bộ năng lượng của nguyên tử gồm động năng và năng lượng nghỉ.","Năng lượng liên kết của một hạt nhân là năng lượng tối thiểu cần thiết phải cung cấp để tách các nuclôn.","Năng lượng liên kết là năng lượng toàn phần của nguyên tử tính trung bình trên số nuclôn.","Năng lượng liên kết là năng lượng liên kết các êlectron và hạt nhân nguyên tử."],"answer":1}$q$::jsonb, 223, $q$Tính độ hụt khối và năng lượng liên kết$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính độ hụt khối và năng lượng liên kết","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là đúng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết là năng lượng toả ra khi các nuclôn riêng rẽ liên kết thành hạt nhân, có độ lớn bằng năng lượng tối thiểu cần cung cấp để phá hạt nhân.</p><p class=\"text-base leading-relaxed my-2\">Các phương án A, C, D nhầm với năng lượng toàn phần của nguyên tử hoặc liên kết êlectron nên sai. Chọn B.</p>","options":["Năng lượng liên kết gồm động năng và năng lượng nghỉ.","Năng lượng liên kết là năng lượng tỏa ra khi các nuclon liên kết với nhau tạo thành hạt nhân.","Năng lượng liên kết là năng lượng toàn phần của nguyên tử tính trung bình trên số nuclon.","Năng lượng liên kết là năng lượng liên kết các electron và hạt nhân nguyên tử."],"answer":1}$q$::jsonb, 223, $q$Tính độ hụt khối và năng lượng liên kết$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính độ hụt khối và năng lượng liên kết","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Giả sử ban đầu có Z prôtôn và N nơtron đứng yên, chưa liên kết với nhau, khối lượng tổng cộng là m0, khi chúng kết hợp lại với nhau để tạo thành một hạt nhân thì có khối lượng m. Gọi ΔE là năng lượng liên kết và c là vận tốc ánh sáng trong chân không. Biểu thức nào sau đây luôn đúng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi các nuclôn liên kết thành hạt nhân thì khối lượng hạt nhân nhỏ hơn tổng khối lượng các nuclôn: $m \\lt m_0$ (có độ hụt khối).</p><p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết $\\Delta E = (m_0 - m)c^2$, không có hệ số $\\frac{1}{2}$, nên B sai. Vậy chọn D.</p>","options":["m = $m_{0}$.","ΔE = $\\frac{1}{2}$($m_{0}$ - m).c$^{2}$","m $\\gt$ $m_{0}$.","m $\\lt$ $m_{0}$."],"answer":3}$q$::jsonb, 223, $q$Tính độ hụt khối và năng lượng liên kết$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính độ hụt khối và năng lượng liên kết","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Giả sử ban đầu có Z prôtôn và N nơtron đứng yên, chưa liên kết với nhau, có khối lượng tổng cộng là m0, khi chúng kết hợp lại với nhau thì tạo thành một hạt nhân có khối lượng m. Gọi c là vận tốc ánh sáng trong chân không. Năng lượng liên kết của hạt nhân này được xác định bởi biểu thức</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết bằng năng lượng tương ứng với độ hụt khối: $\\Delta E = \\Delta m\\,c^2$ với $\\Delta m = m_0 - m$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\Delta E = (m_0 - m)c^2$. Chọn A. D sai thứ nguyên vì chỉ có $c$.</p>","options":["ΔE = ($m_{0}$ - m).c$^{2}$","ΔE = $m_{0}$.c$^{2}$","ΔE = m.c$^{2}$","ΔE = ($m_{0}$ - m).c"],"answer":0}$q$::jsonb, 223, $q$Tính độ hụt khối và năng lượng liên kết$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết riêng là năng lượng liên kết</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết riêng là năng lượng liên kết tính cho một nuclôn: $\\varepsilon = \\frac{W_{lk}}{A}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy chọn A.</p>","options":["tính cho một nuclôn.","tính riêng cho hạt nhân ấy.","của một cặp prôtôn-prôtôn.","của một cặp prôtôn-nơtrôn (nơtron)."],"answer":0}$q$::jsonb, 224, $q$Năng lượng liên kết riêng và độ bền hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết riêng của một hạt nhân được tính bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết riêng bằng thương số của năng lượng liên kết với số nuclôn: $\\varepsilon = \\frac{W_{lk}}{A}$.</p><p class=\"text-base leading-relaxed my-2\">Chọn D. Các phương án A, B, C không đúng định nghĩa.</p>","options":["tích của năng lượng liên kết của hạt nhân với số nuclôn của hạt nhân ấy.","tích của độ hụt khối của hạt nhân với bình phương tốc độ ánh sáng trong chân không.","thương số của khối lượng hạt nhân với bình phương tốc độ ánh sáng trong chân không.","thương số của năng lượng liên kết của hạt nhân với số nuclôn của hạt nhân ấy."],"answer":3}$q$::jsonb, 224, $q$Năng lượng liên kết riêng và độ bền hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết riêng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường cong năng lượng liên kết riêng theo số khối cho thấy $\\varepsilon$ lớn nhất ($\\approx 8{,}8$ MeV/nuclôn) ở các hạt nhân trung bình (số khối khoảng 50–95, quanh sắt).</p><p class=\"text-base leading-relaxed my-2\">Hạt nhân nhẹ và nặng có $\\varepsilon$ nhỏ hơn. Chọn C.</p>","options":["giống nhau với mọi hạt nhân.","lớn nhất với các hạt nhân nhẹ.","lớn nhất với các hạt nhân trung bình.","lớn nhất với các hạt nhân nặng."],"answer":2}$q$::jsonb, 224, $q$Năng lượng liên kết riêng và độ bền hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân nào có năng lượng liên kết riêng lớn nhất?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong các hạt nhân đã cho, sắt ($_{26}^{56}\\mathrm{Fe}$) nằm trong nhóm hạt nhân trung bình nên có năng lượng liên kết riêng lớn nhất ($\\approx 8{,}8$ MeV/nuclôn).</p><p class=\"text-base leading-relaxed my-2\">Heli, cacbon (nhẹ) và urani (nặng) có $\\varepsilon$ nhỏ hơn. Chọn C.</p>","options":["Heli.","Cacbon.","Sắt.","Urani."],"answer":2}$q$::jsonb, 224, $q$Năng lượng liên kết riêng và độ bền hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đại lượng đặc trưng cho mức độ bền vững của hạt nhân là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Mức độ bền vững của hạt nhân được đặc trưng bởi năng lượng liên kết riêng $\\varepsilon$: $\\varepsilon$ càng lớn thì hạt nhân càng bền.</p><p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết, số prôtôn, số nuclôn không so sánh được mức độ bền giữa các hạt nhân có số nuclôn khác nhau. Chọn D.</p>","options":["số prôtôn.","năng lượng liên kết.","số nuclôn.","năng lượng liên kết riêng."],"answer":3}$q$::jsonb, 224, $q$Năng lượng liên kết riêng và độ bền hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân càng bền vững khi có:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân càng bền vững khi năng lượng liên kết riêng càng lớn.</p><p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết (toàn phần) lớn chưa chắc bền vì còn phụ thuộc số nuclôn; số prôtôn hay số nuclôn không quyết định độ bền. Chọn A.</p>","options":["Năng lượng liên kết riêng càng lớn","Số prôtôn càng lớn.","Số nuclôn càng lớn","Năng lượng liên kết càng lớn"],"answer":0}$q$::jsonb, 224, $q$Năng lượng liên kết riêng và độ bền hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong các hạt nhân nguyên tử: $_{2}^{4}{He, }_{26}^{56}{Fe},_{92}^{238}{U, }_{90}^{230}{Th }$ hạt nhân bền vững nhất là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân bền vững nhất là hạt nhân có năng lượng liên kết riêng lớn nhất. Hạt nhân $_{26}^{56}\\mathrm{Fe}$ (số khối trung bình) có $\\varepsilon \\approx 8{,}8$ MeV/nuclôn, lớn hơn He ($\\approx 7{,}1$), Th và U ($\\approx 7{,}6$).</p><p class=\"text-base leading-relaxed my-2\">Chọn C.</p>","options":["$_{2}^{4}{He }$","$_{90}^{230}{Th }$","$_{26}^{56}{Fe}$","$_{92}^{238}{U }$"],"answer":2}$q$::jsonb, 224, $q$Năng lượng liên kết riêng và độ bền hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Các hạt nhân bền vững nhất có năng lượng liên kết riêng lớn nhất vào cỡ</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các hạt nhân bền vững nhất (quanh sắt, số khối 50–95) có năng lượng liên kết riêng lớn nhất cỡ $8{,}8$ MeV/nuclôn.</p><p class=\"text-base leading-relaxed my-2\">Chọn A.</p>","options":["8,8MeV/ nuclon.","7,8MeV/ nuclon.","7,1MeV/ nuclon.","6,8MeV/nuclon."],"answer":0}$q$::jsonb, 224, $q$Năng lượng liên kết riêng và độ bền hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Giả sử hai hạt nhân X và Y có độ hụt khối bằng nhau, nếu số nuclôn của hạt nhân X lớn hơn số nuclôn của hạt nhân Y thì</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Độ hụt khối bằng nhau</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ năng lượng liên kết $W_{lk}=\\Delta m\\,c^2$ của hai hạt nhân bằng nhau (loại A, C).</p><p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết riêng $\\varepsilon=\\frac{W_{lk}}{A}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$A_X>A_Y$ thì $\\varepsilon_X<\\varepsilon_Y$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ hạt nhân Y bền vững hơn X. Chọn D.</p>","options":["năng lượng liên kết của hạt nhân Y lớn hơn năng lượng liên kết của hạt nhân X.","hạt nhân X bền vững hơn hạt nhân Y.","năng lượng liên kết của hạt nhân X lớn hơn năng lượng liên kết của hạt nhân Y.","hạt nhân Y bền vững hơn hạt nhân X."],"answer":3}$q$::jsonb, 224, $q$Năng lượng liên kết riêng và độ bền hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn trong phản ứng hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là đúng khi nói về phản ứng hạt nhân?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phản ứng hạt nhân là mọi quá trình dẫn tới sự biến đổi hạt nhân này thành hạt nhân khác (gồm phóng xạ tự phát và phản ứng kích thích).</p><p class=\"text-base leading-relaxed my-2\">A, B, D chỉ nêu một phần (va chạm, tác động bên ngoài, tự vỡ) nên không đầy đủ. Chọn C.</p>","options":["Phản ứng hạt nhân là sự va chạm giữa các hạt nhân.","Phản ứng hạt nhân là sự tác động từ bên ngoài vào hạt nhân làm hạt nhân đó bị vỡ ra.","Phản ứng hạt nhân là mọi quá trình dẫn đến sự biến đổi của chúng thành các hạt nhân khác.","Phản ứng hạt nhân là quá trình tự hạt nhân vỡ ra."],"answer":2}$q$::jsonb, 225, $q$Định luật bảo toàn trong phản ứng hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn trong phản ứng hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu đúng nhất. Phản ứng hạt nhân được chia ra làm hai loại, đó là:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo SGK, phản ứng hạt nhân chia thành hai loại: tự phát (phóng xạ) và kích thích (hạt nhân tương tác với hạt khác).</p><p class=\"text-base leading-relaxed my-2\">Phân hạch, nhiệt hạch chỉ là các dạng cụ thể của phản ứng kích thích. Chọn A.</p>","options":["phản ứng hạt nhân tự phát và phản ứng hạt nhân kích thích.","phản ứng hạt nhân tự phát và phóng xạ.","phản ứng hạt nhân kích thích và phản ứng phân hạch.","phản ứng hạt nhân tự phát và phản ứng nhiệt hạch."],"answer":0}$q$::jsonb, 225, $q$Định luật bảo toàn trong phản ứng hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn trong phản ứng hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là sai khi nói về phản ứng hạt nhân?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phản ứng hạt nhân bảo toàn điện tích, số khối, động lượng và năng lượng toàn phần, nhưng không bảo toàn khối lượng nghỉ.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ A sai.</p>","options":["Phản ứng hạt nhân tuân theo định luật bảo toàn khối lượng.","Phản ứng hạt nhân tuân theo định luật bảo toàn điện tích.","Phản ứng hạt nhân tuân theo định luật bảo toàn động lượng và năng lượng toàn phần.","Phản ứng hạt nhân tuân theo định luật bảo toàn số khối."],"answer":0}$q$::jsonb, 225, $q$Định luật bảo toàn trong phản ứng hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn trong phản ứng hạt nhân","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Thông tin nào sau đây là sai khi nơi về các định luật bảo toàn trong phản ứng hạt nhân?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các đại lượng bảo toàn: số nuclôn, điện tích, động lượng, năng lượng toàn phần.</p><p class=\"text-base leading-relaxed my-2\">Phương án B nói \"số hạt mang điện\" thay vì tổng điện tích; số hạt mang điện không bảo toàn (vd phóng xạ $\\beta^-$ tạo thêm êlectrôn và prôtôn từ nơtrôn).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ B sai.</p>","options":["Tổng số hạt nuclôn của hạt tương tác bằng tổng số nuclôn của các hạt sản phẩm.","Tổng số các hạt mang điện tích tương tác bằng tổng các hạt mang điện tích sản phẩm.","Tổng năng lượng toàn phần của các hạt tương tác bằng tổng năng lượng toàn phần của các hạt sản phẩm.","Tổng các vectơ động lượng của các hạt tương tác bằng tổng các vectơ động lượng của các hạt sản phẩm."],"answer":1}$q$::jsonb, 225, $q$Định luật bảo toàn trong phản ứng hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn trong phản ứng hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong phản ứng hạt nhân: $_{2}^{4}{He +}_{13}^{27}{Al} \\rightarrow_{15}^{30}{P + X}.$ Hạt X là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Bảo toàn số khối và điện tích: $4+27=30+A_X$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$A_X=1$; $2+13=15+Z_X$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$Z_X=0$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ X là $_0^1n$ (nơtrôn). Chọn B.</p>","options":["pôzitrôn.","nơtrôn.","prôtôn.","êlectrôn."],"answer":1}$q$::jsonb, 225, $q$Định luật bảo toàn trong phản ứng hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn trong phản ứng hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong phản ứng: $x +_{9}^{19}F \\rightarrow_{8}^{16}{O +}_{2}^{4}{He }$ thì x là gì?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Bảo toàn số khối: $A_x+19=16+4$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$A_x=1$; bảo toàn điện tích: $Z_x+9=8+2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$Z_x=1$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ x là $_1^1p$ (prôtôn). Chọn D.</p>","options":["Hạt α .","Hạt β .","Notron.","Prôtôn."],"answer":3}$q$::jsonb, 225, $q$Định luật bảo toàn trong phản ứng hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Năng lượng toả ra của phản ứng hạt nhân","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong một phản ứng hạt nhân, tổng khối lượng các hạt trước phản ứng:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng nghỉ không bảo toàn. Tổng khối lượng trước $m_0$ lớn hơn sau $m$ thì phản ứng tỏa năng lượng, nhỏ hơn thì thu năng lượng.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ có thể lớn hơn hoặc nhỏ hơn. Chọn A.</p>","options":["có thể lớn hay nhỏ hơn tổng khối lượng các hạt sau phản ứng","luôn lớn hơn tổng khối lượng các hạt sau phản ứng","luôn bằng tổng khối lượng các hạt sau phản ứng.","luôn nhỏ hơn tổng khối lượng các hạt sau phản ứng"],"answer":0}$q$::jsonb, 226, $q$Năng lượng toả ra của phản ứng hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân $_{92}^{235}{U }$\\\"bắt\\\" một nơtron rồi vỡ thành hai mảnh nhẹ hơn và kèm theo vài nơtron. Đây là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân nặng $_{92}^{235}U$ hấp thụ nơtrôn rồi vỡ thành hai mảnh và phát vài nơtrôn là phản ứng phân hạch.</p>","options":["phản ứng nhiệt hạch.","hiện tượng phóng xạ.","hiện tượng quang điện.","phản ứng phân hạch."],"answer":3}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Người ta bắn hạt nào vào hạt nhân $_{92}^{235}{U }$ để tạo ra phản ứng phân hạch kích thích</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phân hạch kích thích của $_{92}^{235}U$ xảy ra khi hạt nhân hấp thụ một nơtrôn (nhất là nơtrôn chậm). Nơtrôn không mang điện nên không bị hạt nhân đẩy. Chọn C.</p>","options":["êlectron.","pôzitron.","nơtron.","prôtôn."],"answer":2}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phản ứng hạt nhân nào sau đây là phản ứng phân hạch?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phân hạch: hạt nhân nặng hấp thụ nơtrôn vỡ thành hai mảnh trung bình kèm nơtrôn.</p><p class=\"text-base leading-relaxed my-2\">A là phóng xạ $\\alpha$; B, C là phóng xạ $\\beta$. D: $_0^1n+_{92}^{235}U$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow\\,_{39}^{95}Y+\\,_{53}^{138}I+3\\,_0^1n$ là phân hạch.</p>","options":["$_{84}^{210}{Po} \\rightarrow_{2}^{4}{He} +_{82}^{206}{Pb}$","$_{6}^{12}C \\rightarrow_{- 1}^{0}e +_{7}^{14}N$","$_{7}^{14}N \\rightarrow_{1}^{0}e +_{6}^{12}C$ **","** $_{0}^{1}n +_{92}^{235}U \\rightarrow_{39}^{95}Y +_{53}^{138}I + 3_{0}^{1}n$"],"answer":3}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn trong phản ứng hạt nhân","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Sự phân hạch của hạt nhân urani $_{92}^{235}{U }$ khi hấp thụ một nơtron chậm xảy ra theo nhiều cách. Một trong các cách đó được cho bởi phương trình $_{92}^{235}{U } +_{0}^{1}n \\rightarrow_{54}^{140}{Xe} +_{38}^{94}{Sr +}k_{0}^{1}n$. Số nơtron k được tạo ra trong phản ứng này là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Bảo toàn số khối: $235+1=140+94+k$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$k=2$.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra điện tích: $92=54+38$ (đúng). Chọn D.</p>","options":["k = 3","k = 6","k = 4","k = 2"],"answer":3}$q$::jsonb, 225, $q$Định luật bảo toàn trong phản ứng hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Điều kiện có phản ứng phân hạch dây chuyền tự duy trì là:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phản ứng dây chuyền tự duy trì cần hệ số nhân nơtrôn $k\\ge1$, muốn vậy khối lượng chất phân hạch phải đủ lớn (đạt khối lượng tới hạn). Chọn A.</p>","options":["khối lượng chất phân hạch phải đủ lớn để đảm bảo hệ số nhân nơtron k ≥ 1.","khối lượng chất phân hạch phải nhỏ và hệ số nhân nơtron k $\\lt$ 1.","khối lượng chất phân hạch phải nhỏ và phải có nhiệt độ rất cao.","khối lượng chất phân hạch phải nhỏ và nhiệt độ chất phân hạch phải rất thấp."],"answer":0}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong lò phản ứng hạt nhân, hệ số nhân nơtrôn có trị số:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lò phản ứng hạt nhân cần phản ứng dây chuyền kiểm soát được: $k=1$ (duy trì ổn định).</p><p class=\"text-base leading-relaxed my-2\">$k>1$ làm số phân hạch tăng nhanh, không kiểm soát được (bom); $k<1$ phản ứng tắt dần. Chọn A.</p>","options":["k = 1, phản ứng phân hạch dây chuyền tự duy trì, phản ứng hạt nhân có thể kiểm soát được","k $\\lt$ 1, phản ứng phân hạch dây chuyền tự duy trì, phản ứng hạt nhân không thể kiểm soát được","k $\\gt$ 1, phản ứng phân hạch dây chuyền không xảy ra","k $\\gt$ 1, phản ứng phân hạch dây chuyển tự duy trì, phản ứng hạt nhân có thể kiểm soát được"],"answer":0}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong sự phân hạch của hạt nhân $_{92}^{235}{U }$, gọi k là hệ số nhân nơtron. Phát biểu nào sau đây là đúng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$k<1$: phản ứng tắt dần; $k=1$: dây chuyền duy trì ổn định, kiểm soát được; $k>1$: dây chuyền tự duy trì, năng lượng tăng nhanh, có thể gây nổ.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ B đúng.</p>","options":["Nếu k $\\lt$ 1 thì phản ứng phân hạch dây chuyền xảy ra và năng lượng tỏa ra tăng nhanh.","Nếu k $\\gt$ 1 thì phản ứng phân hạch dây chuyền tự duy trì và có thể gây nên bùng nổ.","Nếu k $\\gt$ 1 thì phản ứng phân hạch dây chuyền không xảy ra.","Nếu k = 1 thì phản ứng phân hạch dây chuyền không xảy ra."],"answer":1}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phản ứng nào trong các phản ứng sau đây là phản ứng tổng hợp hạt nhân (phản ứng nhiệt hạch)?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tổng hợp hạt nhân: các hạt nhân nhẹ kết hợp thành hạt nhân nặng hơn.</p><p class=\"text-base leading-relaxed my-2\">$_1^2H+\\,_1^3H$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow\\,_2^4He+\\,_0^1n$ là phản ứng nhiệt hạch. A là phản ứng hạt nhân kích thích; B, D là phóng xạ $\\alpha$.</p>","options":["$_{2}^{4}{He +}_{7}^{14}N \\rightarrow_{1}^{1}{H +}_{8}^{17}O$","$_{84}^{210}{Po} \\rightarrow_{2}^{4}{He +}_{82}^{206}{Pb}$","$_{1}^{2}{H +}_{1}^{3}H \\rightarrow_{2}^{4}{He +}_{0}^{1}n$","$_{92}^{238}U \\rightarrow_{2}^{4}{He} +_{90}^{234}{Th}$"],"answer":2}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Ở nhiệt độ cao, hai hạt nhân đoteri ($_{1}^{2}H$), kết hợp với nhau tạo thành nhân ($_{2}^{4}{He}$) gọi là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai hạt nhân nhẹ kết hợp thành hạt nhân nặng hơn ở nhiệt độ cao là phản ứng nhiệt hạch.</p>","options":["phản ứng hóa học.","phản ứng nhiệt hạch.","quá trình phóng xạ.","phąn ứng phân hạch."],"answer":1}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Xét phản ứng nhiệt hạch $_{1}^{2}D +_{1}^{2}D \\rightarrow_{2}^{3}{He + X}.$ Hạt X là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phản ứng hạt nhân bảo toàn số nuclôn và điện tích.</p><p class=\"text-base leading-relaxed my-2\">Số nuclôn: $2+2=3+A$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A=1$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Điện tích: $1+1=2+Z$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Z=0$.</p><p class=\"text-base leading-relaxed my-2\">Hạt có $A=1$, $Z=0$ là nơtron $_0^1n$. Vậy X là nơtron (đáp án C). Prôton có $Z=1$; pôzitron có $A=0$; nơtrinô không mang số nuclôn.</p>","options":["proton.","neutrino.","neutron.","positron."],"answer":2}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân nào sau đây <strong>không thể</strong> tham gia phản ứng nhiệt hạch?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phản ứng nhiệt hạch là sự kết hợp các hạt nhân rất nhẹ (như $_1^1H$, $_1^2H$, $_1^3H$) thành hạt nhân nặng hơn.</p><p class=\"text-base leading-relaxed my-2\">$_{94}^{239}Pu$ là hạt nhân rất nặng, dùng cho phản ứng phân hạch, không tham gia nhiệt hạch. Vậy chọn D.</p>","options":["$_{1}^{3}H$","$_{1}^{2}H$","$_{1}^{1}H$ **","** $_{94}^{239}{Pu}$"],"answer":3}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tìm phát biểu sai. Điều kiện để thực hiện phản ứng tổng hợp hạt nhân là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Điều kiện của phản ứng tổng hợp hạt nhân: nhiệt độ rất cao (hàng chục triệu độ), mật độ hạt nhân đủ lớn, thời gian duy trì đủ dài.</p><p class=\"text-base leading-relaxed my-2\">Khối lượng tới hạn là điều kiện của phản ứng phân hạch dây chuyền, không phải của tổng hợp hạt nhân. Vậy phát biểu sai là B.</p>","options":["nhiệt độ cao tới hàng chục triệu độ","khối lượng các hạt nhân phải đạt khối lượng tới hạn.","thời gian duy trì nhiệt độ cao phải đủ lớn.","mật độ hạt nhân phải đủ lớn."],"answer":1}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$)) as v(q, tid, tname)
where not exists (select 1 from public.question_bank b where b.content_hash = public.question_content_hash(v.q));
