from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tại sao để có thể xảy ra phản ứng nhiệt hạch cần phải có nhiệt độ cao hàng chục triệu độ?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các hạt nhân đều mang điện dương nên đẩy nhau bằng lực Cu-lông. Muốn tổng hợp, chúng phải tiến lại rất gần nhau.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Cần nhiệt độ rất cao để hạt nhân có động năng đủ lớn thắng lực đẩy Cu-lông. Vậy chọn B.</p><p class=\"text-base leading-relaxed my-2\">Các phương án còn lại sai: nhiệt độ cao không nhằm phá vỡ hạt nhân hay gây phản ứng hoá học.</p>","options":["Để các electron bứt ra khỏi nguyên tử tạo điều kiện cho các hạt nhân tiếp xúc với nhau.","Để các hạt nhân có động năng đủ lớn, thắng được lực đẩy Cu-lông giữa các hạt nhân.","Để phá vỡ hạt nhân của nguyên tử tham gia phản ứng, kết hợp thành hạt nhân mới.","Để kích thích phản ứng hóa học xảy ra giữa các nguyên tử và phân tử."],"answer":1}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây về phản ứng nhiệt hạch là sai?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt hạch là sự kết hợp các hạt nhân nhẹ thành hạt nhân nặng hơn, cần nhiệt độ rất cao để xảy ra (A, B đúng).</p><p class=\"text-base leading-relaxed my-2\">Năng lượng toả ra do độ hụt khối, không phụ thuộc cách cung cấp năng lượng ban đầu (D đúng).</p><p class=\"text-base leading-relaxed my-2\">Tên \"nhiệt hạch\" xuất phát từ việc phản ứng chỉ xảy ra ở nhiệt độ rất cao, không phải vì nó làm nóng môi trường. Vậy C sai.</p>","options":["Phản ứng nhiệt hạch là sự kết hợp hai hay nhiều hạt nhân nhẹ thành một hạt nhân nặng hơn.","Một trong các điều kiện để phản ứng nhiệt hạch xảy ra là nhiệt độ của nhiên liệu phải rất cao.","Tên gọi phản ứng nhiệt hạch là do nó toả ra năng lượng nhiệt rất lớn, làm nóng môi trường xung quanh lên.","Năng lượng nhiệt hạch không phụ thuộc vào năng lượng cung cấp để phản ứng xảy ra."],"answer":2}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là sai khi nói về phản ứng nhiệt hạch (phản ứng tổng hợp hạt nhân)?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Bom H (bom khinh khí) nổ theo phản ứng nhiệt hạch không kiểm soát được, nên A đúng và B sai.</p><p class=\"text-base leading-relaxed my-2\">C, D đúng với định nghĩa và đặc điểm của phản ứng nhiệt hạch. Vậy chọn B.</p>","options":["Sự nổ của bom H (bom khinh khí) là một phản ứng nhiệt hạch không kiểm soát được.","Sự nổ của bom H (bom khinh khí) là một phản ứng nhiệt hạch kiểm soát được.","Phản ứng nhiệt hạch là quá trình kết hợp hai hay nhiều hạt nhân nhẹ thành một hạt nhân nặng hơn.","Phản ứng nhiệt hạch là loại phản ứng hạt nhân tỏa năng lượng."],"answer":1}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Năng lượng của Mặt Trời và các ngôi sao có được nhờ các phản ứng ở bên trong lõi của chúng. Đó là các phản ứng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng của Mặt Trời và các ngôi sao có được từ phản ứng nhiệt hạch (tổng hợp hydro thành heli) trong lõi, nơi nhiệt độ và áp suất rất cao. Vậy chọn D.</p>","options":["phóng xạ.","hóa học.","phân hạch.","nhiệt hạch."],"answer":3}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phản ứng phân hạch và phản ứng nhiệt hạch đều là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phân hạch là vỡ hạt nhân nặng, nhiệt hạch là tổng hợp hạt nhân nhẹ; hai loại này không giống nhau về cơ chế.</p><p class=\"text-base leading-relaxed my-2\">Điểm chung: tổng khối lượng giảm, cả hai đều toả năng lượng. Vậy chọn D.</p>","options":["phản ứng tổng hợp hạt nhân.","phản ứng phá vở hạt nhân.","phản ứng hạt nhân thu năng lượng.","phản ứng hạt nhân tỏa năng lượng."],"answer":3}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn đáp án <strong>sai</strong> về đặc điểm của tia phóng xạ?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tia phóng xạ không nhìn thấy bằng mắt thường nên A sai.</p><p class=\"text-base leading-relaxed my-2\">Tia phóng xạ có tác dụng ion hoá, gây phản ứng hoá học, phá huỷ tế bào, làm đen kính ảnh (B, C, D đúng).</p>","options":["Có thể quan sát tia phóng xạ bằng mắt thường","Có tác dụng ion hóa môi trường","Gây ra các phản ứng hoá học, phá huỷ tế bào","Làm đen kính ảnh"],"answer":0}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật phóng xạ và chu kì bán rã","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hiện tượng phóng xạ là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phóng xạ là hiện tượng hạt nhân không bền vững tự phân rã, phát ra tia phóng xạ và biến đổi thành hạt nhân khác.</p><p class=\"text-base leading-relaxed my-2\">A, D sai vì \"bị tác động\" (phóng xạ là tự phát); B sai vì hạt nhân bền vững không phân rã. Vậy chọn C.</p>","options":["Hiện tượng hạt nhân không bền vững bị tác động của hạt nhân khác gây ra phân rã, phát ra các tia phóng xạ và biến đổi thành các hạt nhân khác.","Hiện tượng hạt nhân bền vững tự phân rã, phát ra các tia phóng xạ và biến đổi thành các hạt nhân khác.","Hiện tượng hạt nhân không bền vững tự phân rã, phát ra các tia phóng xạ và biến đổi thành các hạt nhân khác.","Hiện tượng hạt nhân bền vững bị tác động của hạt nhân khác gây ra phân rã, phát ra các tia phóng xạ và biến đổi thành các hạt nhân khác."],"answer":2}$q$::jsonb, 229, $q$Định luật phóng xạ và chu kì bán rã$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật phóng xạ và chu kì bán rã","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Quá trình phóng xạ không có đặc tính nào sau đây?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phóng xạ là quá trình tự phát, ngẫu nhiên, là biến đổi hạt nhân, không phụ thuộc điều kiện bên ngoài như nhiệt độ, áp suất.</p><p class=\"text-base leading-relaxed my-2\">Do đó câu \"nhiệt độ càng cao thì phóng xạ càng mạnh\" là sai. Vậy chọn B.</p>","options":["có tính tự phát và không điều khiển được.","nhiệt độ càng cao thì phóng xạ càng mạnh.","có bản chất là quá trình biến đổi hạt nhân.","là một quá trình ngẫu nhiên."],"answer":1}$q$::jsonb, 229, $q$Định luật phóng xạ và chu kì bán rã$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật phóng xạ và chu kì bán rã","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tìm phát biểu sai về phóng xạ?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phóng xạ có bản chất là biến đổi hạt nhân, không phụ thuộc ngoại cảnh, mang tính ngẫu nhiên.</p><p class=\"text-base leading-relaxed my-2\">Vì ngẫu nhiên nên không thể xác định một hạt nhân cụ thể khi nào sẽ phóng xạ. Vậy D sai.</p>","options":["Có bản chất là quá trình biến đổi hạt nhân","Không phụ thuộc vào điều kiện ngoại cảnh","Mang tính ngẫu nhiên","Có thể xác định được một hạt nhân khi nào sẽ phóng xạ"],"answer":3}$q$::jsonb, 229, $q$Định luật phóng xạ và chu kì bán rã$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật phóng xạ và chu kì bán rã","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Quá trình phóng xạ hạt nhân</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân mẹ không bền biến thành hạt nhân con bền hơn nên tổng khối lượng giảm, do đó quá trình phóng xạ luôn toả năng lượng. Vậy chọn B.</p>","options":["thu năng lượng.","toả năng lượng.","không thu, không toả năng lượng.","có trường hợp thu, có trường hợp toả năng lượng."],"answer":1}$q$::jsonb, 229, $q$Định luật phóng xạ và chu kì bán rã$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Người ta nhận biết 3 tia phóng xạ α, β, γ căn cứ vào tính chất nào sau đây?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tia $\\alpha$ (mang điện dương), $\\beta^-$ (mang điện âm), $\\gamma$ (không mang điện) bị lệch khác nhau trong điện trường hoặc từ trường, nên ta nhận biết chúng nhờ tính chất này.</p><p class=\"text-base leading-relaxed my-2\">Ion hoá hay xuyên qua vật chất là tính chất chung, không phân biệt được ba tia. Vậy chọn D.</p>","options":["Các tia phóng xạ ion hoá chất khí.","Các tia phóng xạ có tác dụng ion hoá.","Các tia phóng xạ xuyên qua vật chất.","Các tia phóng xạ lệch trong điện trường hay từ trường."],"answer":3}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một nguyên tử trung hòa có hạt nhân giống với một hạt trong chùm tia α. Tổng số hạt nuclôn và êlectron của nguyên tử này là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt trong chùm tia $\\alpha$ là hạt nhân $_2^4He$ nên nguyên tử trung hoà tương ứng là nguyên tử heli.</p><p class=\"text-base leading-relaxed my-2\">Số nuclôn: $A=4$; số êlectron bằng số prôtôn $=2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Tổng $=4+2=6$. Vậy chọn B.</p>","options":["4.","6.","2.","8."],"answer":1}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nhận xét nào về tia bêta của chất phóng xạ là sai?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tia $\\beta^-$ là êlectron, tốc độ gần bằng tốc độ ánh sáng, có hai loại $\\beta^+$ và $\\beta^-$ (A, B, D đúng).</p><p class=\"text-base leading-relaxed my-2\">Khả năng ion hoá của $\\beta$ yếu hơn $\\alpha$ (nhưng đâm xuyên mạnh hơn). Vậy C sai.</p>","options":["Tia β$^{−}$gồm các hạt β$^{−}$chính là các hạt êlectrôn.","Các hạt β phóng ra với vận tốc rất lớn, có thể gần bằng vận tốc ánh sáng.","Tia β làm ion hoá môi trường mạnh hơn tia alpha .","Có hai loại tia: tia β$^{+}$và tia β$^{−}$."],"answer":2}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đặc điểm nào sau đây không phải của tia β$^{−}$</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tia $\\beta^-$ là dòng êlectron mang điện âm, tốc độ gần bằng tốc độ ánh sáng, bay được vài mét trong không khí.</p><p class=\"text-base leading-relaxed my-2\">Dòng hạt pôzitron là tia $\\beta^+$, nên D không phải của $\\beta^-$.</p>","options":["Mang điện tích âm","Vận tốc gần bằng vận tốc ánh sáng","Bay được vài mét trong không khí và vài mm trong kim loại","Bản chất là dòng hạt positron"],"answer":3}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Điều nào sau đây là <strong>sai</strong> khi nói về tia β$^{−}$?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tia $\\beta^-$ là êlectron, bị lệch về bản dương và lệch nhiều hơn $\\alpha$, ion hoá yếu hơn $\\alpha$ (A, B, D đúng).</p><p class=\"text-base leading-relaxed my-2\">Tia $\\beta^-$ chỉ xuyên được qua chì cỡ vài mm, không phải xentimét. Vậy C sai.</p>","options":["Hạt β$^{−}$thực chất là êlectron.","Trong điện trường, tia β$^{−}$ bị lệch về phía bản dương của tụ điện và lệch nhiều hơn so với tia α.","Tia β$^{−}$có thể xuyên qua một tấm chì dày cỡ xentimét .","Tia β$^{−}$có khả năng ion hoá chất khí kém hơn tia α."],"answer":2}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hạt positron ($_{+ 1}^{0}e)$ là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Pôzitron $_{+1}^{0}e$ là phản hạt của êlectron, chính là hạt $\\beta^+$. Vậy chọn C.</p>","options":["hạt $_{0}^{1}n$","hạt $\\beta^{-}$","hạt  $\\beta^{+}$","hạt $_{1}^{1}H$"],"answer":2}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Positron là phản hạt của</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Pôzitron có cùng khối lượng với êlectron nhưng mang điện tích $+e$, nên là phản hạt của êlectron. Vậy chọn D.</p>","options":["nơtrinô.","notron.","prôton.","electron."],"answer":3}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Điều nào sau đây là đúng khi nói về tia β$^{+}$?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt $\\beta^+$ (pôzitron) có khối lượng bằng êlectron và điện tích $+e$ nên A đúng.</p><p class=\"text-base leading-relaxed my-2\">B sai: tầm bay của $\\beta$ dài hơn $\\alpha$. C sai: đâm xuyên của $\\beta^+$ kém tia Rơn-ghen. D sai: $\\beta^+$ và $\\beta^-$ cùng khối lượng, cùng độ lớn điện tích nên lệch như nhau về độ lớn.</p>","options":["Hạt β$^{+}$có cùng khối lượng với êlectron nhưng mang một điện tích nguyên tố dương.","Tia β$^{+}$có tầm bay ngắn hơn so với tia α","Tia β$^{+}$có khả năng đâm xuyên rất mạnh, giống như tia Rơn-ghen.","Tia β$^{+}$bị lệch đường đi trong điện trường nhiều hơn tia β$^{−}$."],"answer":0}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tia β có khả năng iôn hoá môi trường ... tia α, khả năng đâm xuyên ... tia α.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">So với $\\alpha$, $\\beta$ ion hoá yếu hơn nhưng đâm xuyên mạnh hơn. Vậy chọn A.</p>","options":["yếu hơn/mạnh hơn","yếu hơn/như","mạnh hơn/yếu hơn","mạnh hơn/như"],"answer":0}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong điện trường của cùng một tụ điện</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong điện trường, độ lệch tỉ lệ với $q/m$. Hạt $\\beta$ có khối lượng nhỏ hơn $\\alpha$ hàng nghìn lần nên $q/m$ lớn hơn nhiều.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Tia $\\beta$ lệch nhiều hơn tia $\\alpha$. Vậy chọn D.</p><p class=\"text-base leading-relaxed my-2\">A sai vì chỉ xét điện tích mà bỏ qua khối lượng; B, C sai vì kết luận và lý do không đúng.</p>","options":["tia α lệch nhiều hơn tia β, vì hạt α mang hai điện tích nguyên tố, hạt β chỉ mang một điện tích nguyên tố.","tia β lệch ít hơn, vì hạt β có tốc độ lớn gấp hàng chục lần hạt α.","tia α lệch nhiều hơn vì hạt α to hơn hạt β.","tia β lệch nhiều hơn vì hạt β có khối lượng nhỏ hơn hạt α hàng vài nghìn lần."],"answer":3}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn ý sai. Tia gamma</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tia $\\gamma$ là sóng điện từ bước sóng rất ngắn, chùm phôtôn năng lượng cao, không mang điện nên không lệch trong điện trường.</p><p class=\"text-base leading-relaxed my-2\">Tia $\\gamma$ thường đi kèm phóng xạ $\\alpha$, $\\beta$ (khi hạt nhân con ở trạng thái kích thích) nên D sai.</p>","options":["là sóng điện từ có bước sóng rất ngắn.","là chùm hạt phôtôn có năng lượng cao.","Không bị lệch trong điện trường.","Chỉ được phát ra từ phóng xạ α."],"answer":3}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi nói về tia gamma, phát biểu nào sau đây là sai?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tia γ là sóng điện từ có bước sóng rất ngắn, không mang điện, đâm xuyên mạnh.</p><p class=\"text-base leading-relaxed my-2\">Mọi sóng điện từ trong chân không truyền với tốc độ bằng tốc độ ánh sáng $c$, nên tia γ có tốc độ bằng $c$, không nhỏ hơn $c$.</p><p class=\"text-base leading-relaxed my-2\">Vậy phát biểu sai là D.</p>","options":["Tia γ không mang điện tích","Tia γ có bản chất là sóng điện từ","Tia γ có khả năng đâm xuyên rất mạnh","Tia γ có vận tốc nhỏ hơn vận tốc ánh sáng"],"answer":3}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Vật liệu nào sau đây có tác dụng che chắn mạnh nhất đối với tia γ</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tia γ có khả năng đâm xuyên rất mạnh, cần lớp vật liệu có số khối lớn, khối lượng riêng cao để hấp thụ.</p><p class=\"text-base leading-relaxed my-2\">Trong các vật liệu đã cho, chì có khối lượng riêng và nguyên tử số lớn nhất nên che chắn tia γ tốt nhất.</p>","options":["Sắt","Chì","Nhôm","Bê tông"],"answer":1}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
