from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật phóng xạ và chu kì bán rã","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chất phóng xạ bị phân rã càng nhanh khi chúng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tốc độ phân rã tỉ lệ với $\\lambda$: $H=\\lambda N$, nên $\\lambda$ lớn thì phân rã nhanh. Chọn A.</p><p class=\"text-base leading-relaxed my-2\">Phóng xạ không phụ thuộc nhiệt độ, áp suất; chu kì bán rã lớn thì phân rã chậm.</p>","options":["có hằng số phóng xạ lớn .","ở nhiệt độ cao.","chịu áp lực lớn.","có chu kỳ bán rã lớn."],"answer":0}$q$::jsonb, 229, $q$Định luật phóng xạ và chu kì bán rã$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Độ phóng xạ và bài toán xác định tuổi","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là sai khi nói về độ phóng xạ (hoạt độ phóng xạ)?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Độ phóng xạ $H=\\lambda N$, đơn vị Bq, đặc trưng cho tính phóng xạ mạnh hay yếu; A, B, C đúng.</p><p class=\"text-base leading-relaxed my-2\">Phóng xạ là quá trình hạt nhân, không phụ thuộc nhiệt độ nên D sai. Chọn D (câu hỏi tìm phát biểu sai).</p>","options":["Độ phóng xạ là đại dương đặc trưng cho tính phóng xạ mạnh hay yếu của một lượng chất phóng xạ.","Đơn vị đo độ phóng xạ là Becơren (Bq)","Với mỗi lượng chất phóng xạ xác định thì độ phóng xạ tỉ lệ với số nguyên tử của lượng chất đó.","Độ phóng xạ của một lượng chất phóng xạ phụ thuộc nhiệt độ của lượng chất đó."],"answer":3}$q$::jsonb, 230, $q$Độ phóng xạ và bài toán xác định tuổi$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Độ phóng xạ và bài toán xác định tuổi","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đơn vị nào dưới đây không phải là đơn vị đo độ phóng xạ?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Độ phóng xạ đo bằng số phân rã/s, Bq, Ci.</p><p class=\"text-base leading-relaxed my-2\">u là đơn vị khối lượng nguyên tử nên không phải đơn vị độ phóng xạ. Chọn D.</p>","options":["số phân rã/s.","Ci.","Bq.","u."],"answer":3}$q$::jsonb, 230, $q$Độ phóng xạ và bài toán xác định tuổi$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Độ phóng xạ và bài toán xác định tuổi","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Gọi $H_{0}$ là độ phóng xạ của một lượng chất ở thời điểm t = 0 và λ là hằng số phóng xạ của nó. Khi đó độ phóng xạ của lượng chất ở thời điểm t bất kì là:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật phóng xạ cho độ phóng xạ: $H=H_0 e^{-\\lambda t}$. Chọn A.</p><p class=\"text-base leading-relaxed my-2\">C và D thiếu hoặc đảo vế so với A nên không đúng dạng cần tìm (H theo $H_0$).</p>","options":["H = $H_{0}$. e$^{−λt}$","H = $H_{0}$. e$^{λ/t}$","$H_{0}$ = H.e$^{−λt}$","$H_{0}$ = He$^{λt}$"],"answer":0}$q$::jsonb, 230, $q$Độ phóng xạ và bài toán xác định tuổi$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Độ phóng xạ và bài toán xác định tuổi","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu sai:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Ngoài đồng vị phóng xạ tự nhiên còn có rất nhiều đồng vị phóng xạ nhân tạo (như $^{60}Co$, $^{32}P$). Do đó B sai. Chọn B.</p><p class=\"text-base leading-relaxed my-2\">A, C đúng; D đúng vì $^{14}C$ phát $\\beta^-$ và dùng xác định tuổi cổ vật.</p>","options":["Số lượng hạt nhân phóng xạ giảm theo hàm mũ:","Ngoài đồng vị phóng xạ tự nhiên không có đồng vị phóng xạ nhân tạo nào.","Phương pháp nguyên tử đánh dấu được ứng dụng trong sinh học, y học,.","Đồng vị phóng xạ β$^{−}$ được ứng dụng để xác định tuổi của các cổ vật."],"answer":1}$q$::jsonb, 230, $q$Độ phóng xạ và bài toán xác định tuổi$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Câu nào sai khi nói về ứng dụng của các đồng vị phóng xạ nhân tạo</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đồng vị phóng xạ nhân tạo được dùng làm nguyên tử đánh dấu trong y học, sinh học, xác định tuổi bằng $^{14}C$.</p><p class=\"text-base leading-relaxed my-2\">Không dùng để phóng tên lửa. Chọn A.</p>","options":["Sử dụng các đồng vị phóng xạ nhân tạo để phóng tên lửa.","Sử dụng phương pháp nguyên tử đánh dấu để biết tình trạng bệnh lí của các bộ phận khác nhau của cơ thể, khi thừa hoặc thiếu những nguyên tố nào đó.","Sử dụng phương pháp nguyên tử đánh dấu để biết được chính xác nhu cầu với các nguyên tố khác nhau của cơ thể trong từng thời kì phát triển của nó.","Sử dụng phương pháp xác định tuổi theo lượng Cacbon 14 để xác định niên đại của các cổ vật khai quật được."],"answer":0}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Độ phóng xạ và bài toán xác định tuổi","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Ứng dụng nào sau đây không phải là ứng dụng của đồng vị phóng xạ</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phương pháp nguyên tử đánh dấu, xác định niên đại, điều trị ung thư đều dùng đồng vị phóng xạ.</p><p class=\"text-base leading-relaxed my-2\">Quay phim, chụp ảnh ban đêm dùng tia hồng ngoại, không phải đồng vị phóng xạ. Chọn D.</p>","options":["phương pháp nguyên tử đánh dấu","xác định niên đại cổ vật","điều trị bệnh ung thư","quay phim, chụp ảnh ban đêm"],"answer":3}$q$::jsonb, 230, $q$Độ phóng xạ và bài toán xác định tuổi$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nguyên tắc an toàn khi làm việc với nguồn phóng xạ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Sự cố rò rỉ phóng xạ xảy ra tại nhà máy điện hạt nhân Fu-ku-shi-ma (ngày 11/3/2011) ở Nhật Bản là hậu quả của</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhà máy Fukushima (11/3/2011) bị rò rỉ phóng xạ do trận động đất mạnh gây sóng thần làm mất hệ thống làm mát lò. Chọn A.</p>","options":["động đất, sóng thần.","núi lửa phun trào.","siêu bão nhiệt đới.","biến đổi khí hậu."],"answer":0}$q$::jsonb, 232, $q$Nguyên tắc an toàn khi làm việc với nguồn phóng xạ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liều chiếu xạ và tác hại của phóng xạ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nguồn gây ô nhiễm phóng xạ từ đâu?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các nguồn A, B, C đều gây ô nhiễm phóng xạ nên đáp án đúng là Cả A, B và C. Chọn D.</p>","options":["Chất thải từ các công trường khai thác chất phóng xạ.","Chất thải từ các nhà máy điện nguyên tử, hạt nhân hoặc các chất phóng xạ bị rò rỉ từ các nhà máy này.","Hậu quả các vụ thử vũ khí hạt nhân và vũ khí nguyên tử.","Cả A, B và C"],"answer":3}$q$::jsonb, 231, $q$Liều chiếu xạ và tác hại của phóng xạ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liều chiếu xạ và tác hại của phóng xạ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phơi nhiễm phóng xạ có thể làm</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phơi nhiễm phóng xạ với liều lớn phá huỷ tế bào, gây bệnh tật và có thể gây chết người. Chọn C.</p>","options":["con người thông minh hơn.","con người mạnh mẽ hơn.","gây chết người.","con người hoạt động nhanh hơn."],"answer":2}$q$::jsonb, 231, $q$Liều chiếu xạ và tác hại của phóng xạ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nguyên tắc an toàn khi làm việc với nguồn phóng xạ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn đáp án sai khi nói về những quy tắc an toàn khi làm việc với phóng xạ:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Ba quy tắc chính: giảm thời gian tiếp xúc, tăng khoảng cách, che chắn cơ quan trọng yếu.</p><p class=\"text-base leading-relaxed my-2\">D sai vì khi làm việc với nguồn phóng xạ cần đeo thêm mặt nạ để tránh hít chất phóng xạ. Chọn D.</p>","options":["Giảm thời gian tiếp xúc với nguồn phóng xạ","Tăng khoảng cách từ ta đến nguồn phóng xạ","Đảm bảo che chắn những cơ quan trọng yếu của cơ thể","Mang áo phòng hộ và không cần đeo mặt nạ"],"answer":3}$q$::jsonb, 232, $q$Nguyên tắc an toàn khi làm việc với nguồn phóng xạ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nguyên tắc an toàn khi làm việc với nguồn phóng xạ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Quy tắc nào là không an toàn khi làm việc với chất phóng xạ là gi?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tăng thời gian tiếp xúc làm tăng liều hấp thụ, không an toàn. Chọn A.</p><p class=\"text-base leading-relaxed my-2\">B, C, D là các biện pháp an toàn.</p>","options":["Tăng thời gian tiếp xúc với nguồn phóng xạ","Tăng khoảng cách từ ta đến nguồn phóng xạ","Đảm bảo che chắn những cơ quan trọng yếu của cơ thể","Kiểm tra sức khỏe định kì."],"answer":0}$q$::jsonb, 232, $q$Nguyên tắc an toàn khi làm việc với nguồn phóng xạ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liều chiếu xạ và tác hại của phóng xạ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong hệ đo lường đơn vị quốc tế (SI) đơn vị để đo liều lượng hấp thụ của bức xạ ion hóa là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Liều hấp thụ là năng lượng bức xạ truyền cho một đơn vị khối lượng: đơn vị SI là J/kg, gọi là Gray (Gy). Chọn A.</p><p class=\"text-base leading-relaxed my-2\">Becquerel (Bq) là đơn vị độ phóng xạ, Curie (Ci) cũng vậy, nên B, C, D sai.</p>","options":["J/kg, tên là Gray (Gy)","eV/g hoặc MeV/kg tên là Rơn-ghen (r)","Cal/g hoặc kcal/kg, tên là Cu-ri (Ci)","C/kg, tên là Bêch-cor-ren (Bq)"],"answer":0}$q$::jsonb, 231, $q$Liều chiếu xạ và tác hại của phóng xạ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nguyên tắc sử dụng năng lượng hạt nhân là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong nhà máy điện hạt nhân, năng lượng từ phản ứng hạt nhân làm nóng nước tạo hơi nước quay tua bin máy phát điện (hoặc tạo lực đẩy). Chọn D.</p>","options":["năng lượng từ phản ứng hạt nhân là động năng làm quay tua bin máy phát điện.","năng lượng từ phản ứng hạt nhân là điện năng được sử dụng trực tiếp trong sinh hoạt và sản xuất.","năng lượng từ phản ứng hạt nhân là hóa năng được tích trữ trong các ăcquy.","năng lượng từ phản ứng hạt nhân làm nóng nước để tạo thành hơi nước quay tua bin máy phát điện hoặc tạo lực đẩy."],"answer":3}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong các nhà máy điện nguyên tử hoạt động bình thường hiện nay, phản ứng nào có thể xảy ra trong lò phản ứng hạt nhân của nhà máy để cung cấp năng lượng cho nhà máy hoạt động?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lò phản ứng nhà máy điện hạt nhân dùng phản ứng phân hạch dây chuyền được kiểm soát ở mức tới hạn ($k=1$). Chọn C.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt hạch chưa thực hiện được ở quy mô nhà máy; $k>1$ không kiểm soát là bom.</p>","options":["Phản ứng phân hạch dây chuyền không điều khiển được.","Phản ứng nhiệt hạch có kiểm soát.","Phản ứng phân hạch dây chuyền được khống chế ở mức tới hạn.","Phản ứng phân hạch dây chuyền được khống chế ở mức dưới hạn."],"answer":2}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Các hạt nhân nào sau đây được dùng làm nhiên liệu cho phản ứng phân hạch?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiên liệu phân hạch là $^{235}_{92}U$ và $^{239}_{94}Pu$. Chọn B.</p><p class=\"text-base leading-relaxed my-2\">Hiđrô, đơteri là nhiên liệu của phản ứng nhiệt hạch.</p>","options":["$_{1}^{1}H$ và $_{1}^{2}H$ **","** $_{92}^{235}U$  và  $_{94}^{239}{Pu}$","$_{92}^{235}U$ và $_{1}^{2}H$","$_{1}^{1}H$ và $_{94}^{239}{Pu}$"],"answer":1}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phản ứng phân hạch được thực hiện trong lò phản ứng hạt nhân. Để đảm bảo hệ số nhân nơtron k = 1, người ta dùng các thanh điểu khiển. Những thanh điều khiển có chứa</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Thanh điều khiển làm bằng vật liệu hấp thụ nơtron mạnh như bo và cađimi, để giữ $k=1$. Chọn C.</p>","options":["Urani và Plutoni","nước nặng","Bo và Cadimi","kim loại nặng"],"answer":2}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Thanh điều khiển ngập sâu vào trong lò để hấp thụ số nơtron thừa và đảm bảo số nơtron giải phóng sau mỗi phân hạch là:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Để $k=1$, thanh điều khiển hấp thụ nơtron thừa sao cho trung bình mỗi phân hạch còn 1 nơtron tiếp tục gây phân hạch. Chọn A.</p>","options":["1 notron","nhiều hơn 1 notron","0 notron","tuỳ thuộc kích thước các thanh điều khiển."],"answer":0}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Năng lượng toả ra từ lò phản ứng hạt nhân</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi lò hoạt động ổn định với $k=1$, số phân hạch mỗi giây không đổi nên công suất, năng lượng toả ra không đổi theo thời gian. Chọn A.</p>","options":["Không đổi theo thời gian.","Thay đổi theo theo thời gian.","Tăng theo thời gian.","Giảm theo thời gian."],"answer":0}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một trong những hướng con người đa nghiên cứu để tạo nguồn năng lượng nhân tạo to lớn cho mục đích hòa bình là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng hạt nhân (phân hạch có kiểm soát, nhiệt hạch) là nguồn năng lượng nhân tạo to lớn được nghiên cứu cho mục đích hoà bình. Chọn D.</p>","options":["Năng lượng mặt trời","Năng lượng thủy điện","Năng lượng gió","Năng lượng hạt nhân"],"answer":3}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong điều trị bệnh ung thư, để diệt các tế bào khối u, người ta thường dùng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tia phóng xạ (xạ trị) hoặc hoá chất (hoá trị) là hai cách thường dùng để diệt tế bào khối u.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Chọn C.</p>","options":["cosixin.","chất 5BU.","tia phóng xạ hoặc hóa chất.","EMS."],"answer":2}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Thiết bị chụp cắt lớp phát xạ positron có tên gọi là gì</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Thiết bị chụp cắt lớp phát xạ positron có tên viết tắt là PET (Positron Emission Tomography).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Chọn D. SPECT là chụp cắt lớp phát xạ photon đơn, CT dùng tia X.</p>","options":["X quang","CT","SPECT","PET"],"answer":3}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chất phóng xạ được ứng dụng rộng rãi trong nông nghiệp là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong nông nghiệp, tia phóng xạ được dùng để gây đột biến, cải thiện giống cây trồng.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Chọn B. Các phương án còn lại thuộc y học, công nghiệp, khảo cổ.</p>","options":["Chuẩn đoán hình ảnh và điều trị ung thư","Tạo đột biến cải thiện giống cây trồng","Phát hiện các khiếm khuyết trong vật liệu","Xác định tuổi của các mẫu vật"],"answer":1}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Các tia phóng xạ α, β, γ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nêu một số ứng dụng của chất phóng xạ trong đời sống?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chất phóng xạ dùng trong y học (chẩn đoán hình ảnh, điều trị ung thư), nông nghiệp (tạo đột biến giống), công nghiệp (phát hiện khuyết tật) và khảo cổ (xác định tuổi mẫu vật).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ A, B, C đều đúng. Chọn D.</p>","options":["sử dụng trong y học để chuẩn đoán hình ảnh và điểu trị ung thư.","sử dụng trong nông nghiệp để tạo đột biến cải thiện giống cây trồng.","sử dụng trong công nghiệp để phát hiện các khiếm khuyết trong vật liệu, sử dụng trong khảo cổ để xác định tuổi của các mẫu vật.","Cả A, B và C"],"answer":3}$q$::jsonb, 228, $q$Các tia phóng xạ α, β, γ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Điện tích của hạt nhân $_{6}^{14}C$ là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân C-14 có $Z=6$ prôtôn nên điện tích $q=Ze$.</p><p class=\"text-base leading-relaxed my-2\">$q=6\\cdot1{,}6\\cdot10^{-19}=9{,}6\\cdot10^{-19}$ C.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Chọn C. Phương án D ứng với $Z=8$.</p>","options":["+ 6C.","+ 14C.","+ 9,6.10$^{-19}$C.","+ 12,8.10$^{-19}$C."],"answer":2}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khối lượng của nguyên tử Ar bằng 35,96755u. Số nguyên tử Ar trong 1 mg khí Ar là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng một nguyên tử Ar: $m=35{,}96755\\,u=35{,}96755\\cdot1{,}66055\\cdot10^{-27}\\approx5{,}97\\cdot10^{-26}$ kg.</p><p class=\"text-base leading-relaxed my-2\">Số nguyên tử trong $1$ mg $=10^{-6}$ kg: $N=\\dfrac{10^{-6}}{5{,}97\\cdot10^{-26}}\\approx1{,}674\\cdot10^{19}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Chọn D.</p>","options":["2, 984.10$^{22}$.","2,984. 10$^{19}$.","3,353. 10$^{23}$.","1,674. 10$^{19}$."],"answer":3}$q$::jsonb, 222, $q$Kích thước, khối lượng hạt nhân và đơn vị u$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Biết số Avogadro $N_{A}$ = 6, 02.10$^{23}$ hạt/mol và khối lượng của hạt nhân bằng số khối của nó. Số proton có trong 0,27gam Al là:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Số mol Al: $n=\\dfrac{0{,}27}{27}=0{,}01$ mol.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Số nguyên tử: $N=0{,}01\\cdot6{,}02\\cdot10^{23}=6{,}02\\cdot10^{21}$.</p><p class=\"text-base leading-relaxed my-2\">Mỗi hạt nhân Al có $Z=13$ prôtôn.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Số prôtôn: $13\\cdot6{,}02\\cdot10^{21}\\approx7{,}826\\cdot10^{22}$. Chọn D.</p>","options":["6,826. 10$^{22}$","8, 826.10$^{22}$","9,826. 10$^{22}$","7,826. 10$^{22}$"],"answer":3}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân $^{17}$X có khối lượng 16,994743 u. Biết trong hạt nhân X có 9 notron. Lấy $m_{e}$ = 5,4858.10$^{−4}$u. Khối lượng nguyên tử X bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân có $A=17$, $N=9$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$Z=17-9=8$ (oxi).</p><p class=\"text-base leading-relaxed my-2\">Khối lượng nguyên tử = khối lượng hạt nhân + khối lượng $Z$ electron:</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$m=16{,}994743+8\\cdot5{,}4858\\cdot10^{-4}=16{,}994743+0{,}004389=16{,}999132$ u. Chọn C.</p>","options":["16,999913 u","16,999968 u","16,999132 u","6,999680 u"],"answer":2}$q$::jsonb, 222, $q$Kích thước, khối lượng hạt nhân và đơn vị u$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Công thức gần đúng cho bán kính của hạt nhân là: R = 1,2. 10$^{−15}$. A$^{1/3}$(m) (với A là số khối). Tính khối lượng riêng của hạt nhân</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng hạt nhân $m\\approx A\\cdot u=A\\cdot1{,}66055\\cdot10^{-27}$ kg; thể tích $V=\\dfrac43\\pi R^3=\\dfrac43\\pi(1{,}2\\cdot10^{-15})^3A$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\rho=\\dfrac{1{,}66055\\cdot10^{-27}}{\\frac43\\pi(1{,}2\\cdot10^{-15})^3}\\approx2{,}3\\cdot10^{17}$ kg/m$^3$ (không phụ thuộc $A$). Chọn B.</p>","options":["2,2.10$^{17}$ kg/m$^{3}$","2,3.10$^{17}$ kg/m$^{3}$","2,4.10$^{17}$ kg/m$^{3}$","1,4.10$^{41}$ kg/m$^{3}$"],"answer":1}$q$::jsonb, 222, $q$Kích thước, khối lượng hạt nhân và đơn vị u$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong tự nhiên, clo có 2 đồng vị chủ yếu là $_{17}^{35}{Cl}$ chiếm 75% và $_{17}^{37}{Cl}$ chiếm 25% về số nguyên tử. Lấy $N_{A}$ = 6.10$^{23}$hạt/mol. Tổng cộng số nuclon có trong 1 mol khí clo ($Cl_{2}$) là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối số trung bình của clo: $\\bar A=0{,}75\\cdot35+0{,}25\\cdot37=35{,}5$.</p><p class=\"text-base leading-relaxed my-2\">1 mol $Cl_2$ có $2$ mol nguyên tử</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$2\\cdot6\\cdot10^{23}=1{,}2\\cdot10^{24}$ nguyên tử.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Số nuclôn: $1{,}2\\cdot10^{24}\\cdot35{,}5=4{,}26\\cdot10^{25}$. Chọn A.</p>","options":["4, 26.10$^{25}$ nuclon","2, 22.10$^{25}$ nuclon","2, 9.10$^{25}$ nuclon","3, 58.10$^{25}$ nuclon"],"answer":0}$q$::jsonb, 221, $q$Kí hiệu hạt nhân, số nuclôn, đồng vị$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nitơ tự nhiên có khối lượng nguyên tử là 14,0067u gồm 2 đồng vị là $^{14}$N và $^{15}$N có khối lượng nguyên tử lần lượt là 14,00307u và 15,00011u. Phần trăm của $^{15}$N trong nitơ tự nhiên:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Gọi $x$ là tỉ lệ $^{15}N$: $14{,}00307(1-x)+15{,}00011x=14{,}0067$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$14{,}00307+0{,}99704x=14{,}0067$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$x=\\dfrac{0{,}00363}{0{,}99704}\\approx0{,}00364=0{,}36\\%$. Chọn A.</p>","options":["0,36%.","0,59%.","0,43%.","0,68%."],"answer":0}$q$::jsonb, 222, $q$Kích thước, khối lượng hạt nhân và đơn vị u$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính độ hụt khối và năng lượng liên kết","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Năng lượng toàn phần của một vật đứng yên có khối lượng 1 kg bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng toàn phần của vật đứng yên: $E=mc^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$E=1\\cdot(3\\cdot10^8)^2=9\\cdot10^{16}$ J. Chọn A.</p>","options":["9.10$^{16}$ J","9.10$^{6}$ J","9.10$^{10}$ J","9.10$^{11}$ J"],"answer":0}$q$::jsonb, 223, $q$Tính độ hụt khối và năng lượng liên kết$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính độ hụt khối và năng lượng liên kết","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Biết khối lượng của electron 9,1.10$^{−31}$ kg và tốc độ ánh sáng trong chân không 3.10$^{8}$ m/s. Có thể gia tốc cho electron đến động năng bằng bao nhiêu nếu độ tăng tương đối của khối lượng bằng 5%</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Động năng $W_đ=(m-m_0)c^2=0{,}05\\,m_0c^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$W_đ=0{,}05\\cdot9{,}1\\cdot10^{-31}\\cdot(3\\cdot10^8)^2\\approx4{,}1\\cdot10^{-15}$ J. Chọn C.</p>","options":["8,2.10$^{−14}$ J","8,7.10$^{−14}$ J","4,1.10$^{−15}$ J","8,7.10$^{−16}$ J"],"answer":2}$q$::jsonb, 223, $q$Tính độ hụt khối và năng lượng liên kết$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Biết công suất phát xạ của Mặt Trời là 3,9.10$^{26}$ W, khối lượng Mặt Trời là 2.10$^{30}$ kg. Hỏi sau bao lâu Mặt Trời sẽ cháy hết?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng tương ứng toàn bộ khối lượng: $E=mc^2=2\\cdot10^{30}\\cdot(3\\cdot10^8)^2=1{,}8\\cdot10^{47}$ J.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$t=\\dfrac{E}{P}=\\dfrac{1{,}8\\cdot10^{47}}{3{,}9\\cdot10^{26}}\\approx4{,}6\\cdot10^{20}$ s.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$t\\approx\\dfrac{4{,}6\\cdot10^{20}}{3{,}15\\cdot10^7}\\approx1{,}46\\cdot10^{13}$ năm. Chọn A.</p>","options":["1, 46.10$^{13}$ năm.","1, 46.10$^{16}$ năm.","1, 46.10$^{19}$ năm.","4, 6.10$^{20}$ năm."],"answer":0}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Công suất phát xạ của Mặt Trời là 3,9. 10$^{26}$ W. Cho c = 3. 10$^{8}$ m/s. Trong một giờ khối lượng Mặt Trời giảm mất</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng bức xạ trong 1 giờ: $E=Pt=3{,}9\\cdot10^{26}\\cdot3600$ J.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\Delta m=\\dfrac{E}{c^2}=\\dfrac{3{,}9\\cdot10^{26}\\cdot3600}{9\\cdot10^{16}}=1{,}56\\cdot10^{13}$ kg. Chọn D.</p>","options":["3,12.10$^{13}$ kg","0,78.10$^{13}$ kg","4,68.10$^{13}$ kg","1,56.10$^{13}$ kg"],"answer":3}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Mặt Trời có khối lượng 2.10$^{30}$kg và công suất bức xạ toàn phần là 3,9.10$^{26}$W. Nếu công suất bức xạ không đổi thì sau bao lâu khối lượng giảm đi 0,01%? Xem 1 năm có 365,2425 ngày.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng giảm: $\\Delta m=0{,}01\\%\\cdot2\\cdot10^{30}=2\\cdot10^{26}$ kg.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$E=\\Delta m\\,c^2=1{,}8\\cdot10^{43}$ J</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$t=\\dfrac{E}{P}=\\dfrac{1{,}8\\cdot10^{43}}{3{,}9\\cdot10^{26}}\\approx4{,}62\\cdot10^{16}$ s.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ 1 năm $=365{,}2425\\cdot86400\\approx3{,}1557\\cdot10^7$ s nên $t\\approx1{,}46\\cdot10^9$ năm = 1,46 tỉ năm. Chọn B.</p>","options":["0,85 tỉ năm.","1,46 tỉ năm.","1,54 tỉ năm.","2,12 tỉ năm."],"answer":1}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Mặt Trời có khối lượng 2.10$^{30}$(kg) và công suất bức xạ 3,8.10$^{26}$(W). Nếu công suất bức xạ không đổi thì sau một tỉ năm nữa, phần khối lượng giảm đi là bao nhiêu phần trăm của khối lượng hiện nay. Xem 1 năm có 365,2425 ngày và tốc độ ánh sáng trong chân không 3.10$^{8}$(m/s).</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">$t=10^9\\cdot365{,}2425\\cdot86400\\approx3{,}156\\cdot10^{16}$ s.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$E=Pt=3{,}8\\cdot10^{26}\\cdot3{,}156\\cdot10^{16}\\approx1{,}2\\cdot10^{43}$ J</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\Delta m=\\dfrac{E}{c^2}\\approx1{,}33\\cdot10^{26}$ kg.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Tỉ lệ: $\\dfrac{1{,}33\\cdot10^{26}}{2\\cdot10^{30}}\\approx6{,}7\\cdot10^{-5}\\approx0{,}007\\%$. Chọn C.</p>","options":["0,005%.","0,006%.","0,007%.","0,008%."],"answer":2}$q$::jsonb, 227, $q$Nhà máy điện hạt nhân và phản ứng nhiệt hạch$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính độ hụt khối và năng lượng liên kết","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân urani235U là $_{92}^{235}U$ có năng lượng liên kết riêng là 7,6MeV/ nuclôn. Độ hụt khối của hạt nhân $_{92}^{235}U$ là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng liên kết: $W_{lk}=\\varepsilon\\cdot A=7{,}6\\cdot235=1786$ MeV.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\Delta m=\\dfrac{W_{lk}}{c^2}=\\dfrac{1786}{931{,}5}\\approx1{,}917$ u. Chọn A.</p>","options":["1,917u.","1,942u.","1,754u.","0,751u"],"answer":0}$q$::jsonb, 223, $q$Tính độ hụt khối và năng lượng liên kết$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","difficulty":"kho","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho khối lượng của prôtôn, nơtron; $_{18}^{40}{Ar}; _{3}^{6}{Li}$ lần lượt là 1,0073u; 1,0087 u; 39,9525 u; 6,0145 u và 1 u = 931,5MeV/c$^{2}$. So với năng lượng liên kết riêng của hạt nhân Li thì năng lượng liên kết riêng của hạt nhân $_{18}^{40}{Ar}$</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Ar-40: $Z=18$, $N=22$. $\\Delta m=18\\cdot1{,}0073+22\\cdot1{,}0087-39{,}9525=0{,}3703$ u</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$W_{lk}=0{,}3703\\cdot931{,}5\\approx344{,}9$ MeV</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\varepsilon\\approx8{,}62$ MeV/nuclôn.</p><p class=\"text-base leading-relaxed my-2\">Li-6: $Z=N=3$. $\\Delta m=3\\cdot1{,}0073+3\\cdot1{,}0087-6{,}0145=0{,}0335$ u</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$W_{lk}\\approx31{,}2$ MeV</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\varepsilon\\approx5{,}20$ MeV/nuclôn.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\varepsilon_{Ar}-\\varepsilon_{Li}\\approx3{,}42$ MeV: Ar lớn hơn. Chọn B.</p>","options":["lớn hơn một lượng là 5,20MeV.","lớn hơn một lượng là 3,42MeV.","nhỏ hơn một lượng là 3,42MeV.","nhỏ hơn một lượng là 5,20MeV."],"answer":1}$q$::jsonb, 224, $q$Năng lượng liên kết riêng và độ bền hạt nhân$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật bảo toàn trong phản ứng hạt nhân","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân $_{92}^{235}U$ hấp thụ một hạt notron sinh ra x hạt α, y hạt β và một hạt $_{82}^{208}{Pb}$ và 4 hạt notron. Hỏi x, y có giá trị nào?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phương trình: $n+{}^{235}_{92}U\\to x\\,\\alpha+y\\,\\beta^-+{}^{208}_{82}Pb+4n$.</p><p class=\"text-base leading-relaxed my-2\">Bảo toàn số khối: $1+235=4x+208+4\\cdot1$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow x=6$.</p><p class=\"text-base leading-relaxed my-2\">Bảo toàn điện tích: $92=2x-y+82$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow y=2$. Chọn C.</p>","options":["x = 6, y = 1.","x = 7, y = 2.","x = 6, y = 2.","x = 2, y = 6."],"answer":2}$q$::jsonb, 225, $q$Định luật bảo toàn trong phản ứng hạt nhân$q$)) as v(q, tid, tname)
